function merge(left, right) {
  const out = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) { out.push(left[i]); i++; }
    else { out.push(right[j]); j++; }
  }
  while (i < left.length) { out.push(left[i]); i++; }
  while (j < right.length) { out.push(right[j]); j++; }
  return out;
}
function mergeSort(xs) {
  if (xs.length <= 1) return xs.slice();
  const mid = Math.floor(xs.length / 2);
  return merge(mergeSort(xs.slice(0, mid)), mergeSort(xs.slice(mid)));
}
function run(xs) {
  const sorted = mergeSort(xs);
  let checksum = 0;
  for (let i = 0; i < sorted.length; i++) checksum += sorted[i] * (i + 1);
  return {sorted, checksum};
}

function encodeRle(text) {
  if (!text.length) return [];
  const runs = [];
  let current = text[0], count = 1;
  for (let i = 1; i < text.length; i++) {
    if (text[i] === current) count++;
    else { runs.push([current, count]); current = text[i]; count = 1; }
  }
  runs.push([current, count]);
  return runs;
}
function decodeRle(runs) {
  let out = '';
  for (let i = 0; i < runs.length; i++) {
    const ch = runs[i][0], n = runs[i][1];
    for (let k = 0; k < n; k++) out += ch;
  }
  return out;
}
function run(text) {
  const encoded = encodeRle(text);
  const decoded = decodeRle(encoded);
  return {runs: encoded.length, same: decoded === text, encoded};
}

function sortIntervals(intervals) {
  const copy = [];
  for (let i = 0; i < intervals.length; i++) copy.push([intervals[i][0], intervals[i][1]]);
  for (let i = 1; i < copy.length; i++) {
    const cur = copy[i];
    let j = i - 1;
    while (j >= 0 && (copy[j][0] > cur[0] || (copy[j][0] === cur[0] && copy[j][1] > cur[1]))) {
      copy[j + 1] = copy[j];
      j--;
    }
    copy[j + 1] = cur;
  }
  return copy;
}
function run(intervals) {
  if (!intervals.length) return {merged: [], covered: 0};
  const sorted = sortIntervals(intervals);
  const merged = [sorted[0]];
  for (let i = 1; i < sorted.length; i++) {
    const prev = merged[merged.length - 1], cur = sorted[i];
    if (cur[0] <= prev[1]) {
      if (cur[1] > prev[1]) prev[1] = cur[1];
    } else merged.push(cur);
  }
  let covered = 0;
  for (let i = 0; i < merged.length; i++) covered += merged[i][1] - merged[i][0];
  return {merged, covered};
}

function reconstruct(parent, target) {
  const path = [];
  let cur = target;
  while (cur !== null) { path.push(cur); cur = parent[cur]; }
  path.reverse();
  return path;
}
function run(graph, start, goal) {
  if (start === goal) return {found: true, distance: 0, path: [start]};
  const queue = [start];
  const parent = Object.create(null);
  parent[start] = null;
  let head = 0;
  while (head < queue.length) {
    const node = queue[head++];
    const neighbors = graph[node] || [];
    for (let i = 0; i < neighbors.length; i++) {
      const next = neighbors[i];
      if (!(next in parent)) {
        parent[next] = node;
        if (next === goal) {
          const path = reconstruct(parent, goal);
          return {found: true, distance: path.length - 1, path};
        }
        queue.push(next);
      }
    }
  }
  return {found: false, distance: -1, path: []};
}

function isDigit(c) { return c >= '0' && c <= '9'; }
function isAlpha(c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_'; }
function run(input) {
  const tokens = [];
  let i = 0;
  while (i < input.length) {
    const ch = input[i];
    if (ch === ' ' || ch === '\t' || ch === '\n') { i++; continue; }
    if (isDigit(ch)) {
      let start = i;
      while (i < input.length && isDigit(input[i])) i++;
      tokens.push(['num', Number(input.slice(start, i))]);
    } else if (isAlpha(ch)) {
      let start = i;
      while (i < input.length && (isAlpha(input[i]) || isDigit(input[i]))) i++;
      tokens.push(['id', input.slice(start, i)]);
    } else {
      tokens.push(['op', ch]);
      i++;
    }
  }
  return {count: tokens.length, tokens};
}

function splitLines(text) {
  const out = [];
  let cur = '';
  for (let i = 0; i < text.length; i++) {
    if (text[i] === '\n') { if (cur.trim().length > 0) out.push(cur); cur = ''; }
    else cur += text[i];
  }
  if (cur.trim().length > 0) out.push(cur);
  return out;
}
function parseLine(line) {
  const fields = [];
  let cur = '', inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') inQuotes = !inQuotes;
    else if (ch === ',' && !inQuotes) { fields.push(cur.trim()); cur = ''; }
    else cur += ch;
  }
  fields.push(cur.trim());
  return fields;
}
function run(text) {
  const lines = splitLines(text);
  if (!lines.length) return [];
  const header = parseLine(lines[0]);
  const rows = [];
  for (let r = 1; r < lines.length; r++) {
    const cols = parseLine(lines[r]);
    const obj = {};
    for (let c = 0; c < header.length; c++) obj[header[c]] = c < cols.length ? cols[c] : '';
    rows.push(obj);
  }
  return rows;
}

function matMul(A, B) {
  const rows = A.length, inner = B.length, cols = inner ? B[0].length : 0;
  const out = [];
  for (let i = 0; i < rows; i++) {
    const row = [];
    for (let j = 0; j < cols; j++) {
      let sum = 0;
      for (let k = 0; k < inner; k++) sum += A[i][k] * B[k][j];
      row.push(sum);
    }
    out.push(row);
  }
  return out;
}
function run(A, B) {
  const product = matMul(A, B);
  let trace = 0;
  const rowSums = [];
  for (let i = 0; i < product.length; i++) {
    let rs = 0;
    for (let j = 0; j < product[i].length; j++) {
      rs += product[i][j];
      if (i === j) trace += product[i][j];
    }
    rowSums.push(rs);
  }
  return {product, trace, rowSums};
}

function parseVer(s) {
  const parts = [];
  let cur = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '.') { parts.push(Number(cur)); cur = ''; }
    else cur += s[i];
  }
  parts.push(Number(cur));
  return parts;
}
function cmpVer(a, b) {
  for (let i = 0; i < 3; i++) if (a[i] !== b[i]) return a[i] - b[i];
  return 0;
}
function run(versions, minVer) {
  const floor = parseVer(minVer);
  const kept = [];
  for (let i = 0; i < versions.length; i++) {
    const parsed = parseVer(versions[i]);
    if (cmpVer(parsed, floor) >= 0) kept.push({raw: versions[i], parsed});
  }
  for (let i = 1; i < kept.length; i++) {
    const cur = kept[i];
    let j = i - 1;
    while (j >= 0 && cmpVer(kept[j].parsed, cur.parsed) > 0) { kept[j + 1] = kept[j]; j--; }
    kept[j + 1] = cur;
  }
  return kept.map(item => item.raw);
}

function prune(window, now, span) {
  while (window.length && window[0] <= now - span) window.shift();
}
function run(limit, span, timestamps) {
  const window = [];
  let allowed = 0, blocked = 0;
  const decisions = [];
  for (let i = 0; i < timestamps.length; i++) {
    const t = timestamps[i];
    prune(window, t, span);
    if (window.length < limit) {
      window.push(t);
      allowed++;
      decisions.push(1);
    } else {
      blocked++;
      decisions.push(0);
    }
  }
  return {allowed, blocked, remaining: window.length, decisions};
}

function countItems(items) {
  const counts = Object.create(null);
  for (let i = 0; i < items.length; i++) {
    const key = items[i];
    counts[key] = (counts[key] ?? 0) + 1;
  }
  return counts;
}
function run(items, k) {
  const counts = countItems(items);
  const pairs = [];
  const keys = Object.keys(counts);
  for (let i = 0; i < keys.length; i++) pairs.push([keys[i], counts[keys[i]]]);
  for (let i = 1; i < pairs.length; i++) {
    const cur = pairs[i];
    let j = i - 1;
    while (j >= 0 && (pairs[j][1] < cur[1] || (pairs[j][1] === cur[1] && pairs[j][0] > cur[0]))) {
      pairs[j + 1] = pairs[j];
      j--;
    }
    pairs[j + 1] = cur;
  }
  return {unique: pairs.length, top: pairs.slice(0, k)};
}

async function run(steps) {
  const applied = [];
  try {
    for (let i = 0; i < steps.length; i++) {
      const name = steps[i];
      const delta = await host.readAsync('step:' + name);
      host.store('apply:' + name, delta);
      applied.push({name, delta});
    }
    return {committed: true, count: applied.length, applied};
  } catch (err) {
    for (let i = applied.length - 1; i >= 0; i--) {
      host.store('rollback:' + applied[i].name, -applied[i].delta);
    }
    return {committed: false, error: err, rolledBack: applied.length};
  }
}

async function run(replicas, quorum) {
  const tallies = Object.create(null);
  let failures = 0, leader = null, best = 0;
  for (let i = 0; i < replicas.length; i++) {
    try {
      const vote = await host.readAsync('replica:' + replicas[i]);
      const count = (tallies[vote] ?? 0) + 1;
      tallies[vote] = count;
      if (count > best) { best = count; leader = vote; }
      if (best >= quorum) {
        host.store('consensus', {leader, votes: best, checked: i + 1});
        return {reached: true, leader, votes: best, failures};
      }
    } catch (err) {
      failures++;
    }
  }
  host.store('no-quorum', {best, failures});
  return {reached: false, leader, votes: best, failures};
}

function run(xs, limitMs) {
  const t0 = Date.now();
  let sum = 0;
  for (let i = 0; i < xs.length; i++) sum += xs[i] * xs[i];
  const elapsed = Date.now() - t0;
  console.log('sum=' + sum + ' ms=' + elapsed);
  if (elapsed > limitMs) console.warn('slow:' + elapsed);
  return {sum, elapsed, slow: elapsed > limitMs};
}

function run(records) {
  const ts = Date.now();
  let flagged = 0;
  for (let i = 0; i < records.length; i++) {
    records[i].checkedAt = ts;
    if (records[i].score < 50) {
      records[i].flag = true;
      flagged++;
    }
  }
  console.log('flagged:' + flagged + '/' + records.length);
  return records;
}

function parseKv(text) {
  const out = {};
  let line = '';
  for (let i = 0; i <= text.length; i++) {
    if (i === text.length || text[i] === '\n') {
      const eq = line.indexOf('=');
      if (eq > 0) out[line.slice(0, eq)] = line.slice(eq + 1);
      line = '';
    } else line += text[i];
  }
  return out;
}
async function run(basePath, overridePath, outPath) {
  const baseText = await host.readText(basePath);
  const cfg = parseKv(baseText);
  let hadOverride = true;
  try {
    const overText = await host.readText(overridePath);
    const over = parseKv(overText);
    const keys = Object.keys(over);
    for (let i = 0; i < keys.length; i++) cfg[keys[i]] = over[keys[i]];
  } catch (err) {
    hadOverride = false;
  }
  const keys = Object.keys(cfg);
  const lines = [];
  for (let i = 0; i < keys.length; i++) lines.push(keys[i] + '=' + cfg[keys[i]]);
  await host.writeText(outPath, lines.join('\n'));
  return {hadOverride, cfg};
}

async function run(path, nextContent) {
  let backedUp = false;
  try {
    const prev = await host.readText(path);
    if (prev === nextContent) return {changed: false, backedUp: false};
    await host.writeText(path + '.bak', prev);
    backedUp = true;
  } catch (err) {
    backedUp = false;
  }
  await host.writeText(path, nextContent);
  return {changed: true, backedUp};
}

async function run(url) {
  const res = await host.httpRequest(url, 'GET', '{}', '');
  try {
    const status = await host.httpStatus(res);
    if (status !== 200) {
      console.warn('http-' + status);
      return {ok: false, status, body: ''};
    }
    const body = await host.httpRead(res);
    return {ok: true, status, body};
  } finally {
    await host.httpClose(res);
  }
}

async function run(urls, payload) {
  let sent = 0, failed = 0;
  const replies = [];
  for (let i = 0; i < urls.length; i++) {
    try {
      const reply = await host.httpPost(urls[i], payload);
      sent++;
      replies.push(reply);
    } catch (err) {
      failed++;
      console.error(urls[i] + ':' + err);
    }
  }
  return {sent, failed, replies};
}

async function run(url, knownEtag) {
  const res = await host.httpRequest(url, 'GET', '{"if-none-match":"' + knownEtag + '"}', '');
  try {
    const status = await host.httpStatus(res);
    const hdr = await host.httpHeaders(res);
    if (status === 304) return {modified: false, headers: hdr, body: null};
    const body = await host.httpRead(res);
    return {modified: true, headers: hdr, body};
  } finally {
    await host.httpClose(res);
  }
}

async function run(addr, port, cmds) {
  const sock = await host.socketConnect(addr, port);
  const replies = [];
  let aborted = false;
  try {
    for (let i = 0; i < cmds.length; i++) {
      await host.socketWrite(sock, cmds[i]);
      const reply = await host.socketRead(sock);
      replies.push(reply);
      if (reply === 'ERR') { aborted = true; break; }
    }
  } finally {
    await host.socketClose(sock);
  }
  return {replies, aborted};
}

async function run(targets) {
  for (let i = 0; i < targets.length; i++) {
    const t = targets[i];
    try {
      const sock = await host.socketConnect(t.host, t.port);
      try {
        await host.socketWrite(sock, 'PING');
        const rep = await host.socketRead(sock);
        if (rep === 'PONG') return {healthy: t.host, checked: i + 1};
      } finally {
        await host.socketClose(sock);
      }
    } catch (err) {
      console.warn('down:' + t.host);
    }
  }
  return {healthy: null, checked: targets.length};
}

async function run(selector) {
  const node = await host.domQuery(selector);
  try {
    const state = await host.domGetAttribute(node, 'data-state');
    if (state === 'obsolete') {
      await host.domRemove(node);
      return 'removed';
    }
    const next = state === 'pending' ? 'active' : 'done';
    await host.domSetAttribute(node, 'data-state', next);
    await host.domSetText(node, 'state:' + next);
    return next;
  } finally {
    await host.domRelease(node);
  }
}

async function run(updates) {
  let changed = 0, skipped = 0;
  for (let i = 0; i < updates.length; i++) {
    const [sel, want] = updates[i];
    const node = await host.domQuery(sel);
    try {
      const cur = await host.domGetText(node);
      if (cur !== want) {
        await host.domSetText(node, want);
        changed++;
      } else skipped++;
    } finally {
      await host.domRelease(node);
    }
  }
  return {changed, skipped};
}

function validateForm(form) {
  if (!form.name || form.name.length < 2) return 'short-name';
  if (form.age < 0 || form.age > 150) return 'bad-age';
  return 'ok';
}
async function run(form) {
  const status = validateForm(form);
  const valid = status === 'ok';
  const banner = await host.domQuery('#status');
  try {
    await host.domSetText(banner, valid ? 'Saved:' + form.name : 'Error:' + status);
    await host.domSetAttribute(banner, 'data-valid', valid ? 'true' : 'false');
    console.log('form:' + status);
  } finally {
    await host.domRelease(banner);
  }
  return {valid, status};
}

function run(state, keys) {
  for (let i = 0; i < keys.length; i++) {
    const val = host.readNumber(keys[i]);
    state.total += val;
    state.seen.push(val);
  }
  host.store('total', state.total);
  return state;
}

function run(label, n) {
  let acc = n;
  queueMicrotask(function() {
    host.store('micro:' + label, acc);
  });
  acc = acc * 3;
  console.log('sync:' + label + ':' + acc);
  host.store('sync:' + label, acc);
  return acc;
}

function run(audit, from, to, amount) {
  const src = host.readNumber('bal:' + from);
  const dst = host.readNumber('bal:' + to);
  if (amount <= 0 || src < amount) {
    audit.push({from, to, amount, ok: false});
    console.warn('reject:' + from);
    return {ok: false, src, dst};
  }
  const nextSrc = src - amount, nextDst = dst + amount;
  host.store('bal:' + from, nextSrc);
  host.store('bal:' + to, nextDst);
  audit.push({from, to, amount, ok: true});
  console.info('tx:' + amount);
  return {ok: true, src: nextSrc, dst: nextDst};
}

"use strict";
function rot(index, modulo) {
    return (modulo + (index % modulo)) % modulo;
}

"use strict";
function formatTokenCount(count) {
    if (count >= 1_000_000) {
        const value = count / 1_000_000;
        const floored = Math.floor(value * 10) / 10;
        return floored % 1 === 0 ? `${floored.toFixed(0)}M` : `${floored.toFixed(1)}M`;
    }
    else if (count > 900_000) {
        return '1M';
    }
    else if (count >= 1000) {
        return `${Math.round(count / 1000)}K`;
    }
    return count.toString();
}

"use strict";
function equals(one, other, itemEquals = (a, b) => a === b) {
    if (one === other) {
        return true;
    }
    if (!one || !other) {
        return false;
    }
    if (one.length !== other.length) {
        return false;
    }
    for (let i = 0, len = one.length; i < len; i++) {
        if (!itemEquals(one[i], other[i])) {
            return false;
        }
    }
    return true;
}

"use strict";
